BEGIN TRANSACTION;
CREATE TABLE categories (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        color TEXT DEFAULT '#3B82F6',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    , sort_order INTEGER DEFAULT 0);
CREATE TABLE expenses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        description TEXT NOT NULL,
        amount REAL NOT NULL,
        category TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    , subcategory TEXT DEFAULT "", payment_method TEXT DEFAULT "cash", receipt_no TEXT DEFAULT "", vendor TEXT DEFAULT "", notes TEXT DEFAULT "");
CREATE TABLE order_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_id INTEGER,
        product_id INTEGER,
        quantity INTEGER DEFAULT 1,
        price REAL NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, is_complimentary INTEGER DEFAULT 0, kitchen_notes TEXT, product_name TEXT, part_no INTEGER DEFAULT 1,
        FOREIGN KEY (order_id) REFERENCES orders(id),
        FOREIGN KEY (product_id) REFERENCES products(id)
    );
CREATE TABLE orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        table_id INTEGER,
        total REAL DEFAULT 0,
        status TEXT DEFAULT 'open',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        closed_at TIMESTAMP, discount_type TEXT, discount_value REAL DEFAULT 0, discount_reason TEXT, payment_cash REAL DEFAULT 0, payment_card REAL DEFAULT 0, tip_amount REAL DEFAULT 0, tip_method TEXT, kitchen_ready INTEGER DEFAULT 0, note TEXT DEFAULT "",
        FOREIGN KEY (table_id) REFERENCES tables(id)
    );
CREATE TABLE products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        category_id INTEGER,
        price REAL NOT NULL,
        active INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sort_order INTEGER DEFAULT 0, is_favorite INTEGER DEFAULT 0, stock_item_id INTEGER DEFAULT NULL, is_available INTEGER DEFAULT 1,
        FOREIGN KEY (category_id) REFERENCES categories(id)
    );
CREATE TABLE recipes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id INTEGER NOT NULL,
        stock_item_id INTEGER NOT NULL,
        quantity REAL NOT NULL,
        FOREIGN KEY (product_id) REFERENCES products(id),
        FOREIGN KEY (stock_item_id) REFERENCES stock_items(id)
    );
CREATE TABLE saved_notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL DEFAULT 'NOT',
        content TEXT NOT NULL,
        created_at TEXT DEFAULT (datetime('now','localtime'))
    );

