CREATE TABLE stock_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        unit TEXT DEFAULT 'adet',     -- kg, lt, gr, adet, paket, ml
        quantity REAL DEFAULT 0,
        min_quantity REAL DEFAULT 0,
        cost_per_unit REAL DEFAULT 0,
        category TEXT DEFAULT 'Genel',
        active INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE stock_movements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        stock_item_id INTEGER NOT NULL,
        movement_type TEXT NOT NULL,  -- 'in' / 'out' / 'adjust'
        quantity REAL NOT NULL,
        cost REAL DEFAULT 0,
        reason TEXT DEFAULT 'manuel', -- 'satis','alim','duzeltme','fire'
        description TEXT,
        related_transaction_id INTEGER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, unit TEXT,
        FOREIGN KEY (stock_item_id) REFERENCES stock_items(id)
    );
CREATE TABLE tables (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        zone_id INTEGER,
        status TEXT DEFAULT 'empty',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, table_note TEXT,
        FOREIGN KEY (zone_id) REFERENCES zones(id)
    );
CREATE TABLE telegram_contacts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        chat_id TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        date TEXT NOT NULL,
        type TEXT NOT NULL,           -- 'in' / 'out'
        amount REAL NOT NULL,
        category TEXT DEFAULT 'Genel', -- 'satis','bahsis','masraf','stok_alim','sarf','duzeltme'
        payment_method TEXT DEFAULT 'cash',  -- 'cash' / 'card'
        description TEXT,
        related_order_id INTEGER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE zones (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE INDEX idx_orders_table_status ON orders(table_id, status);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_transactions_date ON transactions(date);
CREATE INDEX idx_stock_movements_item ON stock_movements(stock_item_id);
DELETE FROM "sqlite_sequence";
COMMIT;